		argsCount := strconv.Itoa(len(args))
		return shim.Error("Incorrect number of arguments, expecting 1. Args given:" + argsCount)
	}

	messageAsBytes, err := APIstub.GetState(args[0])

	if err != nil {
		return shim.Error("Message could not be found behind key:" + args[0])
	}

	// Check if the caller has the necessary permissions
	callerMSPID, err := APIstub.GetMSPID()
	if err != nil {
		return shim.Error("Error getting caller's MSPID: " + err.Error())
	}

	allowedMSPIDs := []string{"Org1MSP", "Org2MSP"} // Example allowed MSPIDs
	if !contains(allowedMSPIDs, callerMSPID) {
		return shim.Error("Access denied: Caller is not authorized to read this message")
	}

	return shim.Success(messageAsBytes)
}

func contains(slice []string, item string) bool {
	for _, s := range slice {
		if s == item {
			return true
		}
	}
	return false
}
